// Package proteintranslation translates RNA sequences into proteins.
package proteintranslation

import (
	"errors"
)

// ErrStop indicates that one of the stop codons was read.
var ErrStop = errors.New("stop")

// ErrInvalidBase indicates that an unrecognized codon was read.
var ErrInvalidBase = errors.New("invalid base")

// IsStopCodon checks whether a codon is a stop codon.
func IsStopCodon(c string) bool {
	return c == "UAA" || c == "UAG" || c == "UGA"
}

// FromCodon returns the protein for the given codon.
// If the codon is a stop codon, it returns ErrStop.
// If the codon is unrecognized, it returns ErrInvalidBase.
func FromCodon(c string) (string, error) {
	if IsStopCodon(c) {
		return "", ErrStop
	}

	switch c {
	case "AUG":
		return "Methionine", nil
	case "UUU", "UUC":
		return "Phenylalanine", nil
	case "UUA", "UUG":
		return "Leucine", nil
	case "UCU", "UCC", "UCA", "UCG":
		return "Serine", nil
	case "UAU", "UAC":
		return "Tyrosine", nil
	case "UGU", "UGC":
		return "Cysteine", nil
	case "UGG":
		return "Tryptophan", nil
	default:
		return "", ErrInvalidBase
	}
}

// FromRNA returns the protein sequence for an RNA strand.
// If the sequence contains invalid characters, it returns ErrInvalidBase.
func FromRNA(s string) ([]string, error) {
	var proteins []string
	bases := []rune(s)
	for i := 0; i < len(bases); i += 3 {
		p, err := FromCodon(string(bases[i : i+3]))
		switch err {
		case ErrStop:
			return proteins, nil
		case ErrInvalidBase:
			return nil, err
		default:
			proteins = append(proteins, p)
		}
	}
	return proteins, nil
}

test_code:
package proteintranslation

import (
	"slices"
	"testing"
)

type notNilTestCase struct {
	description string
	err         error
}

var notNilTestCases = []notNilTestCase{
	{
		description: "ErrStop",
		err:         ErrStop,
	},
	{
		description: "ErrInvalidBase",
		err:         ErrInvalidBase,
	},
}

func TestErrorsNotNil(t *testing.T) {
	for _, tc := range notNilTestCases {
		t.Run(tc.description, func(t *testing.T) {
			if tc.err == nil {
				t.Fatalf("FAIL: %s cannot be nil", tc.description)
			}
		})
	}
}

type codonCase struct {
	input         string
	expected      string
	expectedError error
}

var codonTestCases = []codonCase{
	{
		input:         "AUG",
		expected:      "Methionine",
		expectedError: nil,
	},
	{
		input:         "UUU",
		expected:      "Phenylalanine",
		expectedError: nil,
	},
	{
		input:         "UUC",
		expected:      "Phenylalanine",
		expectedError: nil,
	},
	{
		input:         "UUA",
		expected:      "Leucine",
		expectedError: nil,
	},
	{
		input:         "UUG",
		expected:      "Leucine",
		expectedError: nil,
	},
	{
		input:         "UCG",
		expected:      "Serine",
		expectedError: nil,
	},
	{
		input:         "UAU",
		expected:      "Tyrosine",
		expectedError: nil,
	},
	{
		input:         "UAC",
		expected:      "Tyrosine",
		expectedError: nil,
	},
	{
		input:         "UGU",
		expected:      "Cysteine",
		expectedError: nil,
	},
	{
		input:         "UGG",
		expected:      "Tryptophan",
		expectedError: nil,
	},
	{
		input:         "UAA",
		expected:      "",
		expectedError: ErrStop,
	},
	{
		input:         "UAG",
		expected:      "",
		expectedError: ErrStop,
	},
	{
		input:         "UGA",
		expected:      "",
		expectedError: ErrStop,
	},
	{
		input:         "ABC",
		expected:      "",
		expectedError: ErrInvalidBase,
	},
}

func TestCodon(t *testing.T) {
	for _, tc := range codonTestCases {
		t.Run(tc.input, func(t *testing.T) {
			got, err := FromCodon(tc.input)
			switch {
			case tc.expectedError != nil:
				if err != tc.expectedError {
					t.Fatalf("FromCodon(%q) expected error: %q, got: %q", tc.input, tc.expectedError, err)
				}
			case err != nil:
				t.Fatalf("FromCodon(%q) returned unexpected error: %q, want: %q", tc.input, err, tc.expected)
			case got != tc.expected:
				t.Fatalf("FromCodon(%q) = %q, want: %q", tc.input, got, tc.expected)
			}
		})
	}
}

func TestProtein(t *testing.T) {
	for _, tc := range testCases {
		t.Run(tc.description, func(t *testing.T) {
			got, err := FromRNA(tc.input)
			switch {
			case tc.expectedError != nil:
				if err != tc.expectedError {
					t.Fatalf("FromRNA(%q) expected error: %v, got: %v", tc.input, tc.expectedError, err)
				}
			case err != nil:
				t.Fatalf("FromRNA(%q) returned unexpected error: %v, want: %q", tc.input, err, tc.expected)
			case !slices.Equal(got, tc.expected):
				t.Fatalf("FromRNA(%q)\n got: %v\nwant: %v", tc.input, got, tc.expected)
			}
		})
	}
}

func BenchmarkCodon(b *testing.B) {
	for _, test := range codonTestCases {
		for range b.N {
			FromCodon(test.input)
		}
	}
}

func BenchmarkProtein(b *testing.B) {
	for _, test := range testCases {
		for range b.N {
			FromRNA(test.input)
		}
	}
}
